-- AC3 菜單：qmai 線上點餐平台（2026-10-12）
-- 來源：inth5.qmai.com（store_id 221033 / shopId 328009）
-- 可重複執行。

-- ① 分類（22 個）
on conflict (id) do update set sort=excluded.sort, zh=excluded.zh, en=excluded.en, meal=excluded.meal;

-- ② 菜品（125 道）
on conflict (id) do update set canteen_id=excluded.canteen_id, category=excluded.category,
  zh=excluded.zh, en=excluded.en, price=excluded.price, photo=excluded.photo,
  desc_zh=excluded.desc_zh, desc_en=excluded.desc_en, tags=excluded.tags,
  available=excluded.available, sort=excluded.sort;

-- ③ 下架舊 AC3 代表性資料（6 道）
update dishes set available = false where id in (
  'ac3-tuna-pizza', 'ac3-carbonara', 'ac3-bolognese', 'ac3-chicken-sandwich', 'ac3-udon', 'ac3-latte'
);

-- ④ 抽籤黑名單（飲品／甜水）
where not exists (select 1 from roll_blacklist where kind='category' and value='飲品（AC3）');
where not exists (select 1 from roll_blacklist where kind='category' and value='咖啡飲品');
where not exists (select 1 from roll_blacklist where kind='category' and value='糖水系列');
